@startuml

class City {
  + Name : string
}

class H2SLocation {
  + LocationID : int
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + RequestID : int
  + ItemDescription : string
  + RequestedDate : date
  + RequestedTime : time
}

class Vehicle {
  + VehicleID : int
  + StorageCapacity : float
}

class VolunteerDriver {
  + DriverID : int
  + AvailableDays : string[]
}

class PickupRoute {
  + RouteID : int
  + RouteDate : date
}

class Item {
  + ItemID : int
  + Weight : float
  + Dimensions : string
}

class SecondHandArticle {
  + RFIDTag : string
  + Category : string
}

class NonPerishableFood {}

class DistributionCenter {
  + CenterID : int
}

class FoodBank {
  + BankID : int
}

class H2SEmployee {
  + EmployeeID : int
  + Name : string
}

class Client {
  + Name : string
  + HomeAddress : string
  + NeededCategories : string[]
}

class Category {
  + CategoryName : string
}

City "1" -- "*" H2SLocation
H2SLocation "1" -- "0..1" DistributionCenter
H2SLocation "1" -- "0..1" FoodBank

Resident "1" -- "*" PickupRequest
PickupRequest "1" -- "1..*" Item
PickupRequest "1" -- "1" Vehicle : assignedTo
Vehicle "1" -- "*" PickupRoute
VolunteerDriver "*" -- "1" PickupRoute : drives
PickupRoute "1" -- "*" PickupRequest

Item --|> SecondHandArticle
Item --|> NonPerishableFood

SecondHandArticle "*" -- "1" DistributionCenter
NonPerishableFood "*" -- "1" FoodBank

H2SEmployee "1" -- "*" SecondHandArticle : examinesAndTags
H2SEmployee "1" -- "*" Client : callsAndArranges

Client "*" -- "1" DistributionCenter : receivesFrom
SecondHandArticle "*" -- "1" Category
Client "*" -- "*" SecondHandArticle : requestedBy

@enduml

